import { NestFactory } from "@nestjs/core";
import { Logger, StandardSchemaValidationPipe } from "@nestjs/common";

import { AppModule } from "./app.module.js";
import { env } from "./config/env.js";
import { connectDatabase } from "./prisma/db.js";

async function bootstrap() {
  const trustedProxyIps = env.TRUSTED_PROXY_IPS
    .split(",")
    .map((ip) => ip.trim())
    .filter(Boolean);
  await connectDatabase();
  const app = await NestFactory.create(AppModule);
  if (trustedProxyIps.length > 0) {
    app.getHttpAdapter().getInstance().set("trust proxy", trustedProxyIps);
  }
  app.enableCors({
    origin: env.CORS_ORIGIN,
  });
  app.setGlobalPrefix("api");
  app.useGlobalPipes(new StandardSchemaValidationPipe());
  app.enableShutdownHooks();

  await app.listen(env.PORT, "0.0.0.0");
  Logger.log(`Started backend server on http://localhost:${env.PORT}/api`, "Main");
}
await bootstrap();

import postgres from "@prisma/orm-postgres/runtime";
import { env } from "../config/env.js";
import "temporal-polyfill/global";

import type { Contract } from "./contract.d.ts";
import contractJson from "./contract.json" with { type: "json" };

const databaseUrl = env.POSTGRES_URL;

export const db = databaseUrl
  ? postgres<Contract>({ contractJson, url: databaseUrl })
  : postgres<Contract>({ contractJson });

let connection: Promise<void> | undefined;

export function connectDatabase(): Promise<void> {
  connection ??= (async () => {
    try {
      await db.connect();
    } catch (error: unknown) {
      connection = undefined;
      throw error;
    }
  })();
  return connection;
}

import { INestApplication, StandardSchemaValidationPipe } from "@nestjs/common";
import { Test, TestingModule } from "@nestjs/testing";
import request from "supertest";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import type { App } from "supertest/types";

import { AppModule } from "./../src/app.module.js";

describe("AppController (e2e)", () => {
  let app: INestApplication<App>;
  function getRequestTarget(_server = app.getHttpServer()) {
    return _server;
  }

  async function startApplication() {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.useGlobalPipes(new StandardSchemaValidationPipe());
    return app.init();
  }
  beforeAll(startApplication, 30_000);



  it("/ (GET)", async () => {
    const response = await request(getRequestTarget()).get("/").expect(200);
    expect(response.text).toBe("Hello World!");
  });

















  it("returns 404 for an unknown route", async () => {
    await request(getRequestTarget()).get("/__missing_route__").expect(404);
  });






  it("rejects unsupported methods", async () => {
    await request(getRequestTarget()).post("/").send({ unexpected: true }).expect(404);
  });

  afterAll(async () => {
    await app?.close();
  });
});

import { setTimeout as delay } from "node:timers/promises";
import { once } from "node:events";
import { createServer } from "node:net";
import { spawn, type ChildProcess } from "node:child_process";

import { afterEach, expect, it } from "vitest";

const startedProcesses: ChildProcess[] = [];

async function getFreePort(): Promise<number> {
  const server = createServer();
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const address = server.address();
  server.close();
  if (!address || typeof address === "string") {
    throw new Error("Could not allocate a loopback port for the bootstrap test.");
  }
  return address.port;
}

async function waitForServer(url: string, application: ChildProcess, deadline = Date.now() + 60000): Promise<Response> {
  if (application.exitCode !== null) throw new Error(`Generated application exited during startup with code ${application.exitCode}.`);
  try {
    return await fetch(url, { signal: AbortSignal.timeout(500) });
  } catch (error) {
    if (Date.now() >= deadline) throw new Error("Generated application did not become ready", { cause: error });
    await delay(100);
    return waitForServer(url, application, deadline);
  }
}

async function stopApplication(application: ChildProcess): Promise<void> {
  if (application.exitCode !== null) return;
  const exited = once(application, "exit");
  application.kill();
  const timeout = setTimeout(() => { application.kill("SIGKILL"); }, 5000);
  try { await exited; } finally { clearTimeout(timeout); }
}

afterEach(async () => {
  await Promise.all(startedProcesses.splice(0).map(stopApplication));
});

it("boots the compiled application through main.ts", async () => {
  const port = await getFreePort();
  const origin = "https://allowed.example";
  const application = spawn(process.execPath, ["dist/main.js"], {
    env: {
      ...process.env,
      CORS_ORIGIN: origin,
      NODE_ENV: "test",
      PORT: String(port),
    },
    stdio: ["ignore", "pipe", "pipe"],
  });
  startedProcesses.push(application);
  let output = "";
  application.stdout?.on("data", (chunk) => { output += chunk.toString(); });
  application.stderr?.on("data", (chunk) => { output += chunk.toString(); });

  const response = await waitForServer(`http://127.0.0.1:${port}/api`, application).catch((error) => { throw new Error(`${error}\n${output}`); });
  expect(response.status).toBe(200);
  expect(await response.text()).toBe("Hello World!");

  const corsResponse = await fetch(`http://127.0.0.1:${port}/api`, {
    headers: { Origin: origin },
  });
  expect(corsResponse.headers.get("access-control-allow-origin")).toBe(origin);
  const rootResponse = await fetch(`http://127.0.0.1:${port}/`, { redirect: "manual" });
  expect(rootResponse.status).toBe(404);
}, 65_000);

